mapper.select:
select r.* from role r
join user_role ur on r.role_id = ur.role_id
where ur.uid = #{uid}

select sm.id, sm.name, sm.path, sm.icon, sm.role_code, sm.module, sm.module_name
from sys_menu sm
where sm.role_code = #{roleCode}

select ub.uid, ub.username, ub.real_name, ub.id_card, ub.phone, ub.email, ub.create_time, ub.update_time, r.role_name, r.role_code from user_base ub left join user_role ur on ub.uid = ur.uid left join role r on r.role_id = ur.role_id
and ub.username like concat('%', #{username}, '%')
and ub.real_name like concat('%', #{realName}, '%')
and ub.id_card like concat('%', #{idCard}, '%')
and ub.phone like concat('%', #{phone}, '%')
and ub.email like concat('%', #{email}, '%')
and r.role_code = #{roleCode}
and ub.create_time >= #{createTimeBegin}
and ub.create_time <= #{createTimeEnd}
and ub.update_time >= #{updateTimeBegin}
and ub.update_time <= #{updateTimeEnd}
order by ub.create_time desc
LIMIT #{offset}, #{pageSize}

select count(*)
from user_base ub
left join user_role ur on ub.uid = ur.uid
left join role r on r.role_id = ur.role_id


        and ub.username like concat('%', #{username}, '%')


